package com.swmansion.rnscreens.core.utils

import android.view.View
import androidx.annotation.UiThread

/**
 * Provides ids for views and menu items created by the library.
 *
 * Use [PlatformViewIdProvider] when no customisation is needed.
 */
fun interface ViewIdProviding {
    /**
     * Returns a unique view id. Called on the main thread only.
     */
    @UiThread
    fun generateViewId(): Int
}

/**
 * Provides ids generated by [View.generateViewId].
 *
 * Not suitable under React Native, where the renderer assigns small integer ids to views itself.
 */
object PlatformViewIdProvider : ViewIdProviding {
    override fun generateViewId(): Int = View.generateViewId()
}
